const flashcards: KnowledgeFlashcard[] = cardGroups.flatMap(group =>
  group.cards.map(([front, back, detail]) => ({
    id: `eng-amnd-f${String(++cardNumber).padStart(3, "0")}`,
    sectionId: group.sectionId,
    front,
    back,
    sourceType: "knowledgeOrganiser" as const,
    sourceRef: `${group.source} · ${detail}`,
  })),
);

function mc(id: string, sectionId: string, prompt: string, options: string[], answer: string, explanation: string, sourceRef: string): KnowledgeQuestion {
  return { id, type: "multiple-choice", sectionIds: [sectionId], prompt, marks: 1, options, answer, explanation, sourceType: "generatedSupplement", sourceRef };
}

function written(id: string, type: "short-answer" | "long-answer", sectionIds: string[], prompt: string, markingPoints: string[], guidance: string, sourceRef: string): KnowledgeQuestion {
  return { id, type, sectionIds, prompt, marks: markingPoints.length, markingPoints, guidance, sourceType: "generatedSupplement", sourceRef };
}

